mapper.select:
SELECT 
FROM activity_participation
WHERE user_id = #{userId}
AND participate_time >= #{startTime}
AND participate_time < #{endTime}
ORDER BY participate_time DESC

SELECT COUNT(*)
FROM activity_participation
WHERE user_id = #{userId}
AND participate_time >= #{startTime}
AND participate_time < #{endTime}

SELECT COALESCE(SUM(earned_points), 0)
FROM activity_participation
WHERE user_id = #{userId}
AND participate_time >= #{startTime}
AND participate_time < #{endTime}

SELECT COUNT(DISTINCT user_id)
FROM activity_participation
WHERE activity_id = #{activityId}

SELECT activity_type as activityType, COUNT(*) as count
FROM activity_participation
WHERE tenant_id = #{tenantId}

    AND participate_time >= #{startTime}


    AND participate_time < #{endTime}

GROUP BY activity_type
ORDER BY count DESC

SELECT DATE_FORMAT(participate_time, '%Y-%m') as month, COUNT(*) as count
FROM activity_participation
WHERE tenant_id = #{tenantId}
AND YEAR(participate_time) = #{year}
GROUP BY DATE_FORMAT(participate_time, '%Y-%m')
ORDER BY month ASC

SELECT COUNT(*)
FROM activity_participation
WHERE tenant_id = #{tenantId}
AND participate_time >= #{startTime}
AND participate_time < #{endTime}

SELECT COALESCE(SUM(earned_points), 0)
FROM activity_participation
WHERE tenant_id = #{tenantId}
AND participate_time >= #{startTime}
AND participate_time < #{endTime}

SELECT user_id as userId, COUNT(*) as count
FROM activity_participation
WHERE tenant_id = #{tenantId}
AND participate_time >= #{startTime}
AND participate_time < #{endTime}
GROUP BY user_id
ORDER BY count DESC
LIMIT #{limit}
